from collections import Counter

def freq_count(lst):
    """
    Returns a dictionary with elements as keys and their frequencies as values.

    Args:
        lst (list): A list of hashable elements.

    Returns:
        dict: Dictionary mapping each element to its count.
    """
    # Using Counter makes the code concise, but we can also do it manually below if preferred.
    return dict(Counter(lst))

# Alternative manual implementation without importing Counter:
def freq_count_manual(lst):
    frequency = {}
    for item in lst:
        if item in frequency:
            frequency[item] += 1
        else:
            frequency[item] = 1
    return frequency

# Test the function as per your assertion requirement
if __name__ == "__main__":
    assert freq_count([10,10,10,10,20,20,20,20,40,40,50,50,30]) == {10: 4, 20: 4, 40: 2, 50: 2, 30: 1}
print("Test passed!")

# Example usage
data = [10, 10, 10, 10, 20, 20, 20, 20, 40, 40, 50, 50, 30]
result = freq_count(data)
print(result) 
# Output: {10: 4, 20: 4, 40: 2, 50: 2, 30: 1}

